import math
from scipy.integrate import quad, dblquad


def _ccw(P, Q, r):
    def g(t):
        x, y = r * math.cos(t), r * math.sin(t)
        return P(x, y) * (-r * math.sin(t)) + Q(x, y) * (r * math.cos(t))
    return quad(g, 0, 2 * math.pi, limit=200)[0]


def green_check(P, Q, curl, r1, r2):
    line = _ccw(P, Q, r2) - (_ccw(P, Q, r1) if r1 > 0 else 0.0)
    f = lambda r, th: curl(r * math.cos(th), r * math.sin(th)) * r
    area = dblquad(f, 0, 2 * math.pi, lambda th: r1, lambda th: r2)[0]
    return (line, area)
